{"command":"cat > /workspace/names.go <<'EOF'
package main

import (
	"strings"
	"unicode"
	"unicode/utf8"
)

var makePublicFlag = true

var sbTypes = map[string]bool{
	"string": true, "int": true, "bool": true, "byte": true,
	"int8": true, "int16": true, "int32": true, "int64": true,
	"uint16": true, "uint32": true, "float32": true, "float64": true,
}

var goKeywords = map[string]bool{
	"break": true, "default": true, "func": true, "interface": true, "select": true,
	"case": true, "defer": true, "go": true, "map": true, "struct": true,
	"chan": true, "else": true, "goto": true, "package": true, "switch": true,
	"const": true, "fallthrough": true, "if": true, "range": true, "type": true,
	"continue": true, "for": true, "import": true, "return": true, "var": true,
}

var xsdTypeMap = map[string]string{
	"string": "string",
	"boolean": "bool",
	"decimal": "float64",
	"float": "float32",
	"double": "float64",
	"integer": "int32",
	"int": "int32",
	"long": "int64",
	"short": "int16",
	"byte": "int8",
	"unsignedbyte": "byte",
	"unsignedint": "uint32",
	"unsignedlong": "uint64",
	"unsignedshort": "uint16",
	"nonnegativeinteger": "uint32",
	"token": "string",
	"base64binary": "[]byte",
	"hexbinary": "[]byte",
	"datetime": "soap.XSDDateTime",
	"date": "soap.XSDDate",
	"time": "soap.XSDTime",
	"anytype": "AnyType",
	"anyuri": "AnyURI",
	"ncname": "NCName",
}

func sanitizeName(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch {
		case r == '-' || r == '.':
			b.WriteRune('_')
		case r == '@':
			b.WriteString("At")
		case r == '+':
			b.WriteString("Plus")
		case unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_':
			b.WriteRune(r)
		default:
		}
	}
	return b.String()
}

func capFirst(s string) string {
	if s == "" {
		return s
	}
	r, size := utf8.DecodeRuneInString(s)
	return string(unicode.ToUpper(r)) + s[size:]
}

func lowerFirst(s string) string {
	if s == "" {
		return s
	}
	r, size := utf8.DecodeRuneInString(s)
	return string(unicode.ToLower(r)) + s[size:]
}

// extractLocal mirrors observed QName handling: exactly one colon -> part after, otherwise first segment.
func extractLocal(q string) string {
	parts := strings.Split(q, ":")
	if len(parts) == 2 {
		return parts[1]
	}
	return parts[0]
}

// pubSimple: always exported (unless builtin), no keyword handling.
func pubSimple(name string) string {
	if name == "" {
		return "EmptyString"
	}
	s := sanitizeName(name)
	if sbTypes[s] {
		return s
	}
	return sanitizeName(capFirst(name))
}

// pubFlag: used for type definitions, operation message types, enum names, some field names.
func pubFlag(name string) string {
	s := sanitizeName(name)
	if sbTypes[s] {
		return s
	}
	if goKeywords[s] {
		if makePublicFlag {
			return sanitizeName(capFirst(name)) + "_"
		}
		return s + "_"
	}
	if !makePublicFlag {
		return s
	}
	if name == "" {
		return "EmptyString"
	}
	return sanitizeName(capFirst(name))
}

// fieldDisplayName: used for typed element fields.
func fieldDisplayName(name string) string {
	s := sanitizeName(name)
	if s == "string" {
		return "Astring"
	}
	if sbTypes[s] {
		return s
	}
	if goKeywords[s] {
		return sanitizeName(capFirst(name)) + "_"
	}
	if s == "" {
		return "EmptyString"
	}
	return sanitizeName(capFirst(name))
}

// portDisplayName: no sanitisation, no keyword handling.
func portDisplayName(name string) string {
	if !makePublicFlag {
		return name
	}
	if name == "" {
		return "EmptyString"
	}
	if sbTypes[name] {
		return name
	}
	return capFirst(name)
}

// opDisplayName: sanitised, flag sensitive, no keyword handling.
func opDisplayName(name string) string {
	if !makePublicFlag {
		return sanitizeName(name)
	}
	s := sanitizeName(name)
	if sbTypes[s] {
		return s
	}
	if s == "" {
		return "EmptyString"
	}
	return sanitizeName(capFirst(name))
}

func goType(q string) string {
	local := extractLocal(q)
	left := strings.TrimLeft(local, " ")
	if v, ok := xsdTypeMap[strings.ToLower(left)]; ok {
		return v
	}
	if sbTypes[left] {
		return left
	}
	return pubSimple(local)
}

func isBasicType(q string) bool {
	local := extractLocal(q)
	left := strings.TrimLeft(local, " ")
	_, ok := xsdTypeMap[strings.ToLower(left)]
	return ok
}

// type used for a typed element field, including slice/pointer modifiers.
func typedFieldType(q string, maxOccurs string, nillable bool) string {
	gt := goType(q)
	needPtr := nillable || !isBasicType(q)
	if maxOccurs == "unbounded" {
		if needPtr {
			return "[]*" + gt
		}
		return "[]" + gt
	}
	if needPtr {
		return "*" + gt
	}
	return gt
}

func plainPtrType(q string) string {
	gt := goType(q)
	if !isBasicType(q) {
		return "*" + gt
	}
	return gt
}

func docComment(doc string) string {
	if strings.TrimSpace(doc) == "" {
		return ""
	}
	lines := strings.Split(doc, "\n")
	var out []string
	for _, line := range lines {
		t := strings.TrimSpace(line)
		if t == "" {
			out = append(out, "//")
		} else {
			out = append(out, "// "+t)
		}
	}
	return strings.Join(out, "\n")
}
EOF
