	if goKeywords[s] {
		if makePublicFlag {
			return sanitizeName(capFirst(name)) + "_"
		}
		return s + "_"
	}
	if !makePublicFlag {
		return s
	}
	if name == "" {
		return "EmptyString"
	}
	return sanitizeName(capFirst(name))
}

