package main

import (
	"crypto/tls"
	"encoding/xml"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strings"
)

var insecureSkipVerify bool

func parseLocation(location string) ([]byte, error) {
	u, _ := url.Parse(location)
	// dereferencing u intentionally mirrors original behaviour for invalid URLs (nil panic)
	if u.Scheme != "" {
		fmt.Println("🍀 ", "Downloading file", u)
		client := http.DefaultClient
		if insecureSkipVerify {
			tr := http.DefaultTransport.(*http.Transport).Clone()
			tr.TLSClientConfig = &tls.Config{InsecureSkipVerify: true}
			client = &http.Client{Transport: tr}
		}
		resp, err := client.Get(u.String())
		if err != nil {
			return nil, err
		}
		defer resp.Body.Close()
		if resp.StatusCode != 200 {
			return nil, fmt.Errorf("Received response code %d ", resp.StatusCode)
		}
		return io.ReadAll(resp.Body)
	}
	path, err := filepath.Abs(location)
	if err != nil {
		return nil, err
	}
	fmt.Println("🍀 ", "Reading file", path)
	return os.ReadFile(path)
}

func resolveRelativeLocation(base string, ref string) string {
	// remote reference?
	if ru, _ := url.Parse(ref); ru != nil && ru.Scheme != "" {
		return ref
	}
	bu, _ := url.Parse(base)
	if bu != nil && bu.Scheme != "" {
		ru, _ := url.Parse(ref)
		// ResolveReference panics on nil like original would; ru normally non-nil
		return bu.ResolveReference(ru).String()
	}
	if filepath.IsAbs(ref) {
		return ref
	}
	return filepath.Join(filepath.Dir(base), ref)
}

func canonicalLocationKey(loc string) string {
	if u, _ := url.Parse(loc); u != nil && u.Scheme != "" {
		return u.String()
	}
	abs, err := filepath.Abs(loc)
	if err != nil {
		return loc
	}
	return abs
}

type generator struct {
	wsdl        *WSDL
	rawWSDL     []byte
	location    string
	packageName string
	visited     map[string]bool
	allSchemas  []*Schema
}

func newGenerator(location string, packageName string, insecure bool, makePub bool) (*generator, error) {
	insecureSkipVerify = insecure
	makePublicFlag = makePub
	data, err := parseLocation(location)
	if err != nil {
		return nil, err
	}
	var w WSDL
	if err := xml.Unmarshal(data, &w); err != nil {
		return nil, err
	}
	g := &generator{wsdl: &w, rawWSDL: data, location: location, packageName: packageName, visited: make(map[string]bool)}
	// copy initial schemas
	initial := append([]*Schema(nil), w.schemas()...)
	g.allSchemas = append([]*Schema(nil), initial...)
	for _, sch := range initial {
		if sch == nil {
			continue
		}
		for _, imp := range sch.Imports {
			if imp.SchemaLocation == "" {
				fmt.Println("🍀 ", fmt.Sprintf("[WARN] Don't know where to find XSD for %s", imp.Namespace))
				continue
			}
			loc := resolveRelativeLocation(location, imp.SchemaLocation)
			if err := g.loadExternal(loc); err != nil {
				return nil, err
			}
		}
		for _, inc := range sch.Includes {
			loc := resolveRelativeLocation(location, inc.SchemaLocation)
			if err := g.loadExternal(loc); err != nil {
				return nil, err
			}
		}
	}
	// update wsdl types schemas reference for later use (allSchemas used directly)
	return g, nil
}

func (g *generator) loadExternal(loc string) error {
	key := canonicalLocationKey(loc)
	if g.visited[key] {
		return nil
	}
	g.visited[key] = true
	data, err := parseLocation(loc)
	if err != nil {
		return err
	}
	var sch Schema
	if err := xml.Unmarshal(data, &sch); err != nil {
		return err
	}
	sc := sch
	// resolve its imports, then includes (depth-first, dependencies first)
	for _, imp := range sc.Imports {
		if imp.SchemaLocation == "" {
			fmt.Println("🍀 ", fmt.Sprintf("[WARN] Don't know where to find XSD for %s", imp.Namespace))
			continue
		}
		child := resolveRelativeLocation(loc, imp.SchemaLocation)
		if err := g.loadExternal(child); err != nil {
			return err
		}
	}
	for _, inc := range sc.Includes {
		child := resolveRelativeLocation(loc, inc.SchemaLocation)
		if err := g.loadExternal(child); err != nil {
			return err
		}
	}
	g.allSchemas = append(g.allSchemas, &sc)
	return nil
}

var _ = strings.TrimSpace
