	for _, sch := range initial {
		if sch == nil {
			continue
		}
		for _, imp := range sch.Imports {
			if imp.SchemaLocation == "" {
				fmt.Println("🍀 ", fmt.Sprintf("[WARN] Don't know where to find XSD for %s", imp.Namespace))
				continue
			}
			loc := resolveRelativeLocation(location, imp.SchemaLocation)
			if err := g.loadExternal(loc); err != nil {
				return nil, err
			}
		}
		for _, inc := range sch.Includes {
			loc := resolveRelativeLocation(location, inc.SchemaLocation)
			if err := g.loadExternal(loc); err != nil {
				return nil, err
			}
		}
	}
	// update wsdl types schemas reference for later use (allSchemas used directly)
	return g, nil
}

func (g *generator) loadExternal(loc string) error {
	key := canonicalLocationKey(loc)
	if g.visited[key] {
		return nil
	}
	g.visited[key] = true
	data, err := parseLocation(loc)
	if err != nil {
		return err
	}
	var sch Schema
	if err := xml.Unmarshal(data, &sch); err != nil {
		return err
	}
	sc := sch
	// resolve its imports, then includes (depth-first, dependencies first)
	for _, imp := range sc.Imports {
		if imp.SchemaLocation == "" {
			fmt.Println("🍀 ", fmt.Sprintf("[WARN] Don't know where to find XSD for %s", imp.Namespace))
			continue
		}
		child := resolveRelativeLocation(loc, imp.SchemaLocation)
		if err := g.loadExternal(child); err != nil {
			return err
		}
	}
	for _, inc := range sc.Includes {
		child := resolveRelativeLocation(loc, inc.SchemaLocation)
		if err := g.loadExternal(child); err != nil {
			return err
		}
	}
	g.allSchemas = append(g.allSchemas, &sc)
	return nil
}

