func (g *generator) findGlobalAttribute(ref string, current *Schema) *Attribute {
	idx := strings.Index(ref, ":")
	if idx < 0 {
		return nil
	}
	prefix := ref[:idx]
	local := extractLocal(ref)
	ns := make(map[string]string)
	for k, v := range g.wsdl.Namespaces {
