package main

import (
	"flag"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
)

var version = "v0.5.0"

func main() {
	outputFile := flag.String("o", "myservice.go", "File where the generated code will be saved")
	packageName := flag.String("p", "myservice", "Package under which code will be generated")
	directory := flag.String("d", "./", "Directory under which package directory will be created")
	ignoreTLS := flag.Bool("i", false, "Skips TLS Verification")
	makePublic := flag.Bool("make-public", true, "Make the generated types public/exported")
	showVersion := flag.Bool("v", false, "Shows gowsdl version")

	flag.Usage = func() {
		fmt.Fprintf(flag.CommandLine.Output(), "Usage: %s [options] myservice.wsdl\n", os.Args[0])
		flag.PrintDefaults()
	}
	flag.Parse()

	if *showVersion {
		fmt.Println("🍀 ", version)
		return
	}
	if len(os.Args) < 2 {
		flag.Usage()
		return
	}
	wsdlFile := os.Args[len(os.Args)-1]
	if wsdlFile == "" {
		fmt.Println("🍀 ", "WSDL file is required to generate Go proxy")
		os.Exit(1)
	}

	g, err := newGenerator(wsdlFile, *packageName, *ignoreTLS, *makePublic)
	if err != nil {
		fmt.Println("🍀 ", err)
		os.Exit(1)
	}

	// generate server first (in memory) then client, preserving warning order
	serverCode := g.generateServer()
	clientCode := g.generateClient()

	dirPath := filepath.Join(*directory, *packageName)
	_ = os.Mkdir(dirPath, 0744)

	clientPath := filepath.Join(dirPath, *outputFile)
	if err := writeAndFormat(clientPath, clientCode); err != nil {
		fmt.Println("🍀 ", err)
		os.Exit(1)
	}
	serverPath := filepath.Join(dirPath, "server"+*outputFile)
	if err := writeAndFormat(serverPath, serverCode); err != nil {
		fmt.Println("🍀 ", err)
		os.Exit(1)
	}
	fmt.Println("🍀 ", "Done 👍")
}

func writeAndFormat(path string, code string) error {
	if err := os.WriteFile(path, []byte(code), 0644); err != nil {
		return err
	}
	formatted, err := format.Source([]byte(code))
	if err != nil {
		return err
	}
	if err := os.WriteFile(path, formatted, 0644); err != nil {
		return err
	}
	return nil
}
