package main

import (
	"fmt"
	"strings"
)

// ---------- finders ----------

func (g *generator) findMessage(attr string) *Message {
	if attr == "" {
		return nil
	}
	local := extractLocal(attr)
	for _, m := range g.wsdl.Messages {
		if m.Name == local {
			return m
		}
	}
	return nil
}

func (g *generator) findElement(attr string) *Element {
	local := extractLocal(attr)
	for _, sch := range g.allSchemas {
		for _, el := range sch.Elements {
			if strings.EqualFold(el.Name, local) {
				return el
			}
		}
	}
	return nil
}

func (g *generator) findGlobalAttribute(ref string, current *Schema) *Attribute {
	idx := strings.Index(ref, ":")
	if idx < 0 {
		return nil
	}
	prefix := ref[:idx]
	local := extractLocal(ref)
	ns := make(map[string]string)
	for k, v := range g.wsdl.Namespaces {
		ns[k] = v
	}
	if current != nil {
		for k, v := range current.Namespaces {
			ns[k] = v
		}
	}
	uri, ok := ns[prefix]
	if !ok {
		return nil
	}
	for _, sch := range g.allSchemas {
		if sch.TargetNamespace != uri {
			continue
		}
		for _, a := range sch.Attributes {
			if a.Name == local {
				return a
			}
		}
	}
	return nil
}

func (g *generator) soapAction(pt *PortType, op *PortOperation) string {
	for _, b := range g.wsdl.Bindings {
		if !strings.EqualFold(extractLocal(b.Type), pt.Name) {
			continue
		}
		for _, bop := range b.Operations {
			if bop.Name != op.Name {
				continue
			}
			if bop.SoapOperation != nil && bop.SoapOperation.SoapAction != "" {
				return bop.SoapOperation.SoapAction
			}
			return "''"
		}
	}
	return "''"
}

// ---------- operation type resolution ----------

func (g *generator) resolveOpType(op *PortOperation, input bool) string {
	var ref *MessageRef
	if input {
		ref = op.Input
	} else {
		ref = op.Output
	}
	if ref == nil || ref.Message == "" {
		return ""
	}
	msg := g.findMessage(ref.Message)
	if msg == nil {
		return ""
	}
	if len(msg.Parts) == 0 {
		fmt.Println("🍀 ", fmt.Sprintf("[WARN] %s message doesn't have any parts, ignoring message...", msg.Name))
		return ""
	}
	part := msg.Parts[0]
	if part.Type != "" {
		return pubFlag(extractLocal(part.Type))
	}
	if part.Element != "" {
		elem := g.findElement(part.Element)
		if elem == nil {
			return ""
		}
		if elem.Type != "" {
			return pubFlag(extractLocal(elem.Type))
		}
		return pubFlag(elem.Name)
	}
	return ""
}

func opDisplayType(resolved string) string {
	return pubFlag(resolved)
}

// ---------- unique XMLName for complex types ----------

func (g *generator) uniqueElementForType() map[string]string {
	m := make(map[string]string)
	ambiguous := make(map[string]bool)
	register := func(typeQ string, elemName string) {
		if typeQ == "" {
			return
		}
		local := extractLocal(typeQ)
		if local == "" {
			return
		}
		if ambiguous[local] {
			return
		}
		if existing, ok := m[local]; ok {
			if existing != elemName {
				delete(m, local)
				ambiguous[local] = true
			}
			return
		}
		m[local] = elemName
	}
	var walkCT func(ct *ComplexType)
	var walkElements func(list []*Element)
	walkElements = func(list []*Element) {
		for _, el := range list {
			register(el.Type, el.Name)
			if el.ComplexType != nil {
				walkCT(el.ComplexType)
			}
		}
	}
	walkCT = func(ct *ComplexType) {
		if ct == nil {
			return
		}
		// sequences elements
		for _, seq := range ct.Sequences {
			walkElements(seq.Elements)
			for _, ch := range seq.Choices {
				walkElements(ch.Elements)
			}
		}
		for _, ch := range ct.Choices {
			walkElements(ch.Elements)
		}
		for _, all := range ct.Alls {
			walkElements(all.Elements)
		}
		if ct.ComplexContent != nil && ct.ComplexContent.Extension != nil {
			ext := ct.ComplexContent.Extension
			for _, seq := range ext.Sequences {
				walkElements(seq.Elements)
				for _, ch := range seq.Choices {
					walkElements(ch.Elements)
				}
			}
			for _, ch := range ext.Choices {
				walkElements(ch.Elements)
			}
		}
	}
	for _, sch := range g.allSchemas {
		for _, el := range sch.Elements {
			register(el.Type, el.Name)
			if el.ComplexType != nil {
				walkCT(el.ComplexType)
			}
		}
		for _, ct := range sch.ComplexTypes {
			walkCT(ct)
		}
	}
	return m
}

// ---------- simple types ----------

func simpleTypeGoType(st *SimpleType) string {
	if st == nil {
		return "interface{}"
	}
	if st.Restriction != nil && st.Restriction.Base != "" {
		return goType(st.Restriction.Base)
	}
	if st.List != nil {
		return "[]" + goType(st.List.ItemType)
	}
	if st.Union != nil {
		return "string"
	}
	return "interface{}"
}

func (g *generator) writeSimpleTypeDef(b *strings.Builder, typeName string, st *SimpleType) {
	if st == nil {
		return
	}
	if dc := docComment(annotationDoc(st.Annotation)); dc != "" {
		b.WriteString(dc + "\n\n")
	}
	gt := simpleTypeGoType(st)
	fmt.Fprintf(b, "type %s %s\n\n", typeName, gt)
	if st.Restriction != nil && len(st.Restriction.Enumerations) > 0 {
		b.WriteString("const (\n")
		for _, e := range st.Restriction.Enumerations {
			constName := typeName + pubFlag(e.Value)
			if dc := docComment(annotationDoc(e.Annotation)); dc != "" {
				b.WriteString("\n" + dc + "\n")
			} else {
				b.WriteString("\n")
			}
			fmt.Fprintf(b, "%s %s = \"%s\"\n", constName, typeName, e.Value)
		}
		b.WriteString(")\n\n")
	}
}

// ---------- field rendering ----------

func (g *generator) renderElementField(el *Element, sch *Schema) string {
	// ref
	if el.Ref != "" {
		local := extractLocal(el.Ref)
		fieldName := pubFlag(local)
		ft := typedFieldType(el.Ref, el.MaxOccurs, el.Nillable)
		return fmt.Sprintf("%s %s `xml:\"%s,omitempty\" json:\"%s,omitempty\"`", fieldName, ft, local, local)
	}
	if el.Type != "" {
		fieldName := fieldDisplayName(el.Name)
		ft := typedFieldType(el.Type, el.MaxOccurs, el.Nillable)
		prefix := ""
		if dc := docComment(annotationDoc(el.Annotation)); dc != "" {
			prefix = dc + "\n"
		}
		return fmt.Sprintf("%s%s %s `xml:\"%s,omitempty\" json:\"%s,omitempty\"`", prefix, fieldName, ft, el.Name, el.Name)
	}
	if el.SimpleType != nil {
		fieldName := pubSimple(el.Name)
		ft := g.anonSimpleFieldType(el.SimpleType)
		prefix := ""
		if dc := docComment(annotationDoc(el.Annotation)); dc != "" {
			prefix = dc + "\n\n"
		}
		return fmt.Sprintf("%s%s %s `xml:\"%s,omitempty\" json:\"%s,omitempty\"`", prefix, fieldName, ft, el.Name, el.Name)
	}
	// anonymous complex or empty
	{
		fieldName := pubFlag(el.Name)
		var inner string
		if el.ComplexType != nil {
			inner = g.inlineStructType(el.ComplexType, sch)
		} else {
			inner = "struct {\n}"
		}
		if el.MaxOccurs == "unbounded" {
			inner = "[]" + inner
		}
		return fmt.Sprintf("%s %s `xml:\"%s,omitempty\" json:\"%s,omitempty\"`", fieldName, inner, el.Name, el.Name)
	}
}

func (g *generator) anonSimpleFieldType(st *SimpleType) string {
	if st.List != nil {
		gt := goType(st.List.ItemType)
		if !isBasicType(st.List.ItemType) {
			return "[]*" + gt
		}
		return "[]" + gt
	}
	if st.Restriction != nil {
		return plainPtrType(st.Restriction.Base)
	}
	// union / empty
	return plainPtrType("")
}

func (g *generator) renderAttribute(attr *Attribute, sch *Schema) string {
	effective := attr
	effectiveName := attr.Name
	if attr.Ref != "" {
		found := g.findGlobalAttribute(attr.Ref, sch)
		if found != nil {
			effective = found
			effectiveName = extractLocal(attr.Ref)
		} else {
			effective = &Attribute{}
			effectiveName = ""
		}
	}
	fieldName := pubSimple(effectiveName)
	var ft string
	if effective.Type != "" {
		ft = plainPtrType(effective.Type)
	} else if effective.SimpleType != nil && effective.SimpleType.Restriction != nil {
		ft = plainPtrType(effective.SimpleType.Restriction.Base)
	} else {
		ft = "string"
	}
	prefix := ""
	if dc := docComment(annotationDoc(attr.Annotation)); dc != "" {
		prefix = dc + "\n\n"
	}
	if sch != nil && sch.TargetNamespace != "" {
		return fmt.Sprintf("%s%s %s `xml:\"%s %s,attr,omitempty\" json:\"%s,omitempty\"`", prefix, fieldName, ft, sch.TargetNamespace, effectiveName, effectiveName)
	}
	return fmt.Sprintf("%s%s %s `xml:\"%s,attr,omitempty\" json:\"%s,omitempty\"`", prefix, fieldName, ft, effectiveName, effectiveName)
}

func (g *generator) renderElements(list []*Element, sch *Schema) []string {
	var out []string
	for _, el := range list {
		out = append(out, g.renderElementField(el, sch))
	}
	return out
}

// struct fields for a complex type
func (g *generator) complexTypeFields(ct *ComplexType, sch *Schema, nested bool) []string {
	if ct == nil {
		return nil
	}
	// complex content extension
	if ct.ComplexContent != nil && ct.ComplexContent.Extension != nil {
		ext := ct.ComplexContent.Extension
		var out []string
		out = append(out, plainPtrType(ext.Base))
		for _, seq := range ext.Sequences {
			out = append(out, g.renderElements(seq.Elements, sch)...)
		}
		for _, ch := range ext.Choices {
			out = append(out, g.renderElements(ch.Elements, sch)...)
		}
		for _, seq := range ext.Sequences {
			for _, ch := range seq.Choices {
				out = append(out, g.renderElements(ch.Elements, sch)...)
			}
		}
		for _, a := range ext.Attributes {
			out = append(out, g.renderAttribute(a, sch))
		}
		return out
	}
	if ct.SimpleContent != nil && ct.SimpleContent.Extension != nil {
		ext := ct.SimpleContent.Extension
		var out []string
		valType := plainPtrType(ext.Base)
		out = append(out, fmt.Sprintf("Value %s `xml:\",chardata\" json:\"-,\"`", valType))
		for _, a := range ext.Attributes {
			out = append(out, g.renderAttribute(a, sch))
		}
		return out
	}
	var out []string
	for _, seq := range ct.Sequences {
		out = append(out, g.renderElements(seq.Elements, sch)...)
	}
	if !nested {
		for _, seq := range ct.Sequences {
			for range seq.Anys {
				out = append(out, "Items []string `xml:\",any\" json:\"items,omitempty\"`")
			}
		}
	}
	for _, ch := range ct.Choices {
		out = append(out, g.renderElements(ch.Elements, sch)...)
	}
	for _, seq := range ct.Sequences {
		for _, ch := range seq.Choices {
			out = append(out, g.renderElements(ch.Elements, sch)...)
		}
	}
	for _, all := range ct.Alls {
		out = append(out, g.renderElements(all.Elements, sch)...)
	}
	for _, a := range ct.Attributes {
		out = append(out, g.renderAttribute(a, sch))
	}
	return out
}

func (g *generator) inlineStructType(ct *ComplexType, sch *Schema) string {
	fields := g.complexTypeFields(ct, sch, true)
	if len(fields) == 0 {
		return "struct {\n}"
	}
	return "struct {\n" + strings.Join(fields, "\n\n") + "\n}"
}

func (g *generator) writeStructType(b *strings.Builder, defName string, xmlNameTag string, hasXMLName bool, ct *ComplexType, sch *Schema) {
	fmt.Fprintf(b, "type %s struct {\n", defName)
	var entries []string
	if hasXMLName {
		entries = append(entries, fmt.Sprintf("XMLName xml.Name `xml:\"%s\"`", xmlNameTag))
	}
	entries = append(entries, g.complexTypeFields(ct, sch, false)...)
	if len(entries) > 0 {
		b.WriteString(strings.Join(entries, "\n\n") + "\n")
	}
	b.WriteString("}\n\n")
}

// ---------- generation: types ----------

func (g *generator) generateTypes(b *strings.Builder) {
	unique := g.uniqueElementForType()
	for _, sch := range g.allSchemas {
		// Simple types first
		for _, st := range sch.SimpleTypes {
			typeName := pubFlag(st.Name)
			g.writeSimpleTypeDef(b, typeName, st)
		}
		// Elements
		for _, el := range sch.Elements {
			if el.Name == "" {
				continue
			}
			if el.Type != "" {
				gt := goType(el.Type)
				defName := pubFlag(el.Name)
				if gt == defName {
					continue
				}
				fmt.Fprintf(b, "type %s %s\n\n", defName, gt)
				// date/time methods
				var recv, soapType string
				switch gt {
				case "soap.XSDDateTime":
					recv, soapType = "xdt", "soap.XSDDateTime"
				case "soap.XSDDate":
					recv, soapType = "xd", "soap.XSDDate"
				case "soap.XSDTime":
					recv, soapType = "xt", "soap.XSDTime"
				}
				if recv != "" {
					fmt.Fprintf(b, "func (%s %s) MarshalXML(e *xml.Encoder, start xml.StartElement) error {\n\treturn %s(%s).MarshalXML(e, start)\n}\n\n", recv, defName, soapType, recv)
					fmt.Fprintf(b, "func (%s *%s) UnmarshalXML(d *xml.Decoder, start xml.StartElement) error {\n\treturn (*%s)(%s).UnmarshalXML(d, start)\n}\n\n", recv, defName, soapType, recv)
				}
				continue
			}
			if el.SimpleType != nil {
				defName := pubFlag(el.Name)
				g.writeSimpleTypeDef(b, defName, el.SimpleType)
				continue
			}
			if el.ComplexType != nil {
				defName := pubFlag(el.Name)
				tag := fmt.Sprintf("%s %s", sch.TargetNamespace, el.Name)
				g.writeStructType(b, defName, tag, true, el.ComplexType, sch)
				continue
			}
			// no type: skip
		}
		// Complex types
		for _, ct := range sch.ComplexTypes {
			defName := pubFlag(ct.Name)
			// simple string alias special case
			if ct.SimpleContent != nil && ct.SimpleContent.Extension != nil {
				ext := ct.SimpleContent.Extension
				if len(ext.Attributes) == 0 && goType(ext.Base) == "string" {
					fmt.Fprintf(b, "type %s string\n\n", defName)
					continue
				}
			}
			var tag string
			var has bool
			if elemName, ok := unique[ct.Name]; ok {
				tag = fmt.Sprintf("%s %s", sch.TargetNamespace, elemName)
				has = true
			}
			g.writeStructType(b, defName, tag, has, ct, sch)
		}
	}
}

// ---------- client ----------

func (g *generator) generateClient() string {
	var b strings.Builder
	b.WriteString("\n// Code generated by gowsdl DO NOT EDIT.\n\n")
	fmt.Fprintf(&b, "package %s\n\n", g.packageName)
	b.WriteString("import (\n\t\"context\"\n\t\"encoding/xml\"\n\t\"time\"\n\t\"github.com/hooklift/gowsdl/soap\"\n)\n\n")
	b.WriteString("// against \"unused imports\"\nvar _ time.Time\nvar _ xml.Name\n\n")
	b.WriteString("type AnyType struct {\n\tInnerXML string `xml:\",innerxml\"`\n}\n\n")
	b.WriteString("type AnyURI string\n\n")
	b.WriteString("type NCName string\n\n")

	g.generateTypes(&b)

	// Port types
	if g.wsdl != nil {
		for _, pt := range g.wsdl.PortTypes {
			iface := portDisplayName(pt.Name)
			priv := lowerFirst(iface)
			// interface
			fmt.Fprintf(&b, "type %s interface {\n", iface)
			// compute interface types (I,O per op)
			type opInfo struct {
				op   *PortOperation
				req  string
				resp string
				name string
			}
			var infos []opInfo
			for _, op := range pt.Operations {
				req := opDisplayType(g.resolveOpType(op, true))
				resp := opDisplayType(g.resolveOpType(op, false))
				infos = append(infos, opInfo{op, req, resp, opDisplayName(op.Name)})
			}
			for _, info := range infos {
				b.WriteString("\n")
				if len(info.op.Faults) > 0 {
					b.WriteString("// Error can be either of the following types:\n//\n")
					for _, f := range info.op.Faults {
						fmt.Fprintf(&b, "//   - %s\n", f.Name)
					}
				}
				if info.op.Documentation != "" {
					fmt.Fprintf(&b, "/* %s */\n", info.op.Documentation)
				}
				if info.resp != "" {
					fmt.Fprintf(&b, "%s(request *%s) (*%s, error)\n\n", info.name, info.req, info.resp)
					fmt.Fprintf(&b, "%sContext(ctx context.Context, request *%s) (*%s, error)\n", info.name, info.req, info.resp)
				} else {
					fmt.Fprintf(&b, "%s(request *%s) error\n\n", info.name, info.req)
					fmt.Fprintf(&b, "%sContext(ctx context.Context, request *%s) error\n", info.name, info.req)
				}
			}
			b.WriteString("}\n\n")

			fmt.Fprintf(&b, "type %s struct {\n\tclient *soap.Client\n}\n\n", priv)
			fmt.Fprintf(&b, "func New%s(client *soap.Client) %s {\n\treturn &%s{\n\t\tclient: client,\n\t}\n}\n\n", iface, iface, priv)

			// implementation (resolve again I,O per op)
			for _, op := range pt.Operations {
				req := opDisplayType(g.resolveOpType(op, true))
				resp := opDisplayType(g.resolveOpType(op, false))
				name := opDisplayName(op.Name)
				action := g.soapAction(pt, op)
				if resp != "" {
					fmt.Fprintf(&b, "func (service *%s) %sContext(ctx context.Context, request *%s) (*%s, error) {\n", priv, name, req, resp)
					fmt.Fprintf(&b, "\tresponse := new(%s)\n", resp)
					fmt.Fprintf(&b, "\terr := service.client.CallContext(ctx, \"%s\", request, response)\n", action)
					b.WriteString("\tif err != nil {\n\t\treturn nil, err\n\t}\n\n\treturn response, nil\n}\n\n")
					fmt.Fprintf(&b, "func (service *%s) %s(request *%s) (*%s, error) {\n", priv, name, req, resp)
					fmt.Fprintf(&b, "\treturn service.%sContext(\n\t\tcontext.Background(),\n\t\trequest,\n\t)\n}\n\n", name)
				} else {
					fmt.Fprintf(&b, "func (service *%s) %sContext(ctx context.Context, request *%s) error {\n", priv, name, req)
					fmt.Fprintf(&b, "\terr := service.client.CallContext(ctx, \"%s\", request, struct{}{})\n", action)
					b.WriteString("\tif err != nil {\n\t\treturn err\n\t}\n\n\treturn nil\n}\n\n")
					fmt.Fprintf(&b, "func (service *%s) %s(request *%s) error {\n", priv, name, req)
					fmt.Fprintf(&b, "\treturn service.%sContext(\n\t\tcontext.Background(),\n\t\trequest,\n\t)\n}\n\n", name)
				}
			}
		}
	}
	return b.String()
}

// ---------- server ----------

type flatOp struct {
	reqA, respB, reqB, respC, reqC string
}

func (g *generator) generateServer() string {
	// Phase A/B/C resolution ordering
	var ops []*PortOperation
	if g.wsdl != nil {
		for _, pt := range g.wsdl.PortTypes {
			ops = append(ops, pt.Operations...)
		}
	}
	var flats []flatOp
	for _, op := range ops {
		_ = op
		flats = append(flats, flatOp{})
	}
	// A: request only, flattened
	for i, op := range ops {
		flats[i].reqA = opDisplayType(g.resolveOpType(op, true))
	}
	// B: response then request
	for i, op := range ops {
		flats[i].respB = opDisplayType(g.resolveOpType(op, false))
		flats[i].reqB = opDisplayType(g.resolveOpType(op, true))
	}
	// C: response, request, request
	for i, op := range ops {
		flats[i].respC = opDisplayType(g.resolveOpType(op, false))
		flats[i].reqC = opDisplayType(g.resolveOpType(op, true))
		_ = opDisplayType(g.resolveOpType(op, true))
	}

	var b strings.Builder
	b.WriteString("\n// Code generated by gowsdl DO NOT EDIT.\n\n")
	fmt.Fprintf(&b, "package %s\n\n", g.packageName)
	b.WriteString("import (\n\t\"fmt\"\n\t\"errors\"\n\t\"reflect\"\n\t\"strings\"\n\t\"encoding/xml\"\n\t\"net/http\"\n)\n\n")
	// wsdl var
	b.WriteString("var wsdl = `")
	b.Write(g.rawWSDL)
	b.WriteString("`\n\n")
	b.WriteString("var WSDLUndefinedError = errors.New(\"Server was unable to process request. --> Object reference not set to an instance of an object.\")\n\n")

	b.WriteString("type SOAPEnvelopeRequest struct {\n\tXMLName xml.Name `xml:\"http://schemas.xmlsoap.org/soap/envelope/ Envelope\"`\n\tBody SOAPBodyRequest\n}\n\n")

	// SOAPBodyRequest
	b.WriteString("type SOAPBodyRequest struct {\n\tXMLName xml.Name `xml:\"http://schemas.xmlsoap.org/soap/envelope/ Body\"`\n")
	var reqEntries []string
	for _, f := range flats {
		reqEntries = append(reqEntries, fmt.Sprintf("%s *%s `xml:,omitempty`", f.reqA, f.reqA))
	}
	if len(reqEntries) > 0 {
		b.WriteString("\n" + strings.Join(reqEntries, "\n\n") + "\n")
	}
	b.WriteString("}\n\n")

	b.WriteString("type SOAPEnvelopeResponse struct {\n\tXMLName xml.Name `xml:\"soap:Envelope\"`\n\tPrefixSoap string `xml:\"xmlns:soap,attr\"`\n\tPrefixXsi string `xml:\"xmlns:xsi,attr\"`\n\tPrefixXsd string `xml:\"xmlns:xsd,attr\"`\n\n\tBody SOAPBodyResponse\n}\n\n")
	b.WriteString("func NewSOAPEnvelopResponse() *SOAPEnvelopeResponse {\n\treturn &SOAPEnvelopeResponse{\n\t\tPrefixSoap: \"http://schemas.xmlsoap.org/soap/envelope/\",\n\t\tPrefixXsd: \"http://www.w3.org/2001/XMLSchema\",\n\t\tPrefixXsi: \"http://www.w3.org/2001/XMLSchema-instance\",\n\t}\n}\n\n")
	b.WriteString("type Fault struct {\n\tXMLName xml.Name `xml:\"SOAP-ENV:Fault\"`\n\tSpace string `xml:\"xmlns:SOAP-ENV,omitempty,attr\"`\n\n\tCode string `xml:\"faultcode,omitempty\"`\n\tString string `xml:\"faultstring,omitempty\"`\n\tActor string `xml:\"faultactor,omitempty\"`\n\tDetail string `xml:\"detail,omitempty\"`\n}\n\n")

	// SOAPBodyResponse
	b.WriteString("type SOAPBodyResponse struct {\n\tXMLName xml.Name `xml:\"soap:Body\"`\n\tFault *Fault `xml:\",omitempty\"`\n")
	var respEntries []string
	for _, f := range flats {
		respEntries = append(respEntries, fmt.Sprintf("%s *%s `xml:\",omitempty\"`", f.reqB, f.respB))
	}
	if len(respEntries) > 0 {
		b.WriteString("\n" + strings.Join(respEntries, "\n\n") + "\n")
	}
	b.WriteString("}\n\n")

	for _, f := range flats {
		fmt.Fprintf(&b, "func (service *SOAPBodyRequest) %sFunc(request *%s) (*%s, error) {\n\treturn nil, WSDLUndefinedError\n}\n\n", f.reqC, f.reqC, f.respC)
	}

	// fixed call / endpoint
	b.WriteString(serverCallCode)
	return b.String()
}

const serverCallCode = `func (service *SOAPEnvelopeRequest) call(w http.ResponseWriter, r *http.Request) {
	w.Header().Add("Content-Type", "text/xml; charset=utf-8")
	val := reflect.ValueOf(&service.Body).Elem()
	n := val.NumField()
	var field reflect.Value
	var name string
	find := false

	if r.Method == http.MethodGet {
		w.Write([]byte(wsdl))
		return
	}

	resp := NewSOAPEnvelopResponse()
	defer func() {
		if r := recover(); r != nil {
			resp.Body.Fault = &Fault{}
			resp.Body.Fault.Space = "http://schemas.xmlsoap.org/soap/envelope/"
			resp.Body.Fault.Code = "soap:Server"
			resp.Body.Fault.Detail = fmt.Sprintf("%v", r)
			resp.Body.Fault.String = fmt.Sprintf("%v", r)
		}
		xml.NewEncoder(w).Encode(resp)
	}()

	header := r.Header.Get("Content-Type")
	if strings.Index(header, "application/soap+xml") >= 0 {
		panic("Could not find an appropriate Transport Binding to invoke.")
	}

	err := xml.NewDecoder(r.Body).Decode(service)
	if err != nil {
		panic(err)
	}

	for i := 0; i < n; i++ {
		field = val.Field(i)
		name = val.Type().Field(i).Name
		if field.Kind() != reflect.Ptr {
			continue
		}
		if field.IsNil() {
			continue
		}
		if field.IsValid() {
			find = true
			break
		}
	}

	if !find {
		panic(WSDLUndefinedError)
	} else {
		m := val.Addr().MethodByName(name + "Func")
		if !m.IsValid() {
			panic(WSDLUndefinedError)
		}

		vals := m.Call([]reflect.Value{field})
		if vals[1].IsNil() {
			reflect.ValueOf(&resp.Body).Elem().FieldByName(name).Set(vals[0])
		} else {
			panic(vals[1].Interface())
		}
	}

}

func Endpoint(w http.ResponseWriter, r *http.Request) {
	request := SOAPEnvelopeRequest{}
	request.call(w, r)
}
