    import pathlib
    name=os.path.basename(wsdl_path)
    shutil.copy(wsdl_path, os.path.join(work,name))
    # also copy any extra files in same dir as wsdl? For assets, copy whole assets as some may import?
    r=subprocess.run([exe]+extra+[name], capture_output=True, text=True, cwd=work)
    outputs={}
    pkg=os.path.join(work,"myservice")
    if os.path.isdir(pkg):
        for f in sorted(os.listdir(pkg)):
            outputs[f]=open(os.path.join(pkg,f),'rb').read()
    return r, outputs

def compare(wsdl, extra=[]):
    r1,o1=run(ORIG, wsdl, BASE+"/orig", extra)
    r2,o2=run(MINE, wsdl, BASE+"/mine", extra)
    ok=True
    if r1.returncode!=r2.returncode:
        print("  exit diff", r1.returncode, r2.returncode); ok=False
    if r1.stdout!=r2.stdout:
        print("  stdout diff:")
        print("   orig:", r1.stdout[:2000])
        print("   mine:", r2.stdout[:2000]); ok=False
    if r1.stderr!=r2.stderr:
        # ignore panic stacks? show limited
        print("  stderr diff orig:", r1.stderr[:500], " mine:", r2.stderr[:500]); ok=False
    if set(o1)!=set(o2):
        print("  files diff", list(o1), list(o2)); ok=False
    else:
        for k in o1:
            if o1[k]!=o2[k]:
                print(f"  file {k} diff len {len(o1[k])} vs {len(o2[k])}")
                # write diff
                open("/tmp/diff_orig.txt","wb").write(o1[k]); open("/tmp/diff_mine.txt","wb").write(o2[k])
                ok=False
    print(("PASS" if ok else "FAIL"), wsdl, extra)
    return ok

if __name__=="__main__":
    files=sys.argv[1:]
    if not files:
        files=sorted([os.path.join("/workspace/assets",f) for f in os.listdir("/workspace/assets")])
    for f in files: compare(f)
PY
