import subprocess, os, shutil, sys
ORIG="/workspace/executable"
MINE="/tmp/myexe"
BASE="/tmp/difftest"
def run_one(exe,label,args,files):
    work=os.path.join(BASE,label); shutil.rmtree(work,ignore_errors=True); os.makedirs(work,exist_ok=True)
    for name,content in files.items():
        p=os.path.join(work,name); os.makedirs(os.path.dirname(p),exist_ok=True); open(p,"w",encoding="utf-8",errors="surrogateescape").write(content)
    r=subprocess.run([exe]+args, capture_output=True, text=True, cwd=work)
    outputs={}
    for root,dirs,fs in os.walk(work):
        for f in fs:
            path=os.path.join(root,f)
            rel=os.path.relpath(path,work)
            if rel in files: continue
            outputs[rel]=open(path,'rb').read()
    stdout=r.stdout.replace(work,"WORK")
    stderr=r.stderr
    # stderr contains panic stack addresses/names; normalize away for comparison? Keep code only if not panic
    return r.returncode, stdout, stderr, outputs

def compare(title,args,files):
    rc1,s1,e1,o1=run_one(ORIG,"orig",args,files)
    rc2,s2,e2,o2=run_one(MINE,"mine",args,files)
    ok=True; reasons=[]
    if rc1!=rc2: ok=False; reasons.append(f"rc {rc1}!={rc2}")
    if s1!=s2: ok=False; reasons.append(f"stdout orig={s1!r} mine={s2!r}")
    # compare stderr only for non-panic cases (flag errors are deterministic)
    if "panic:" not in e1 and e1!=e2: ok=False; reasons.append(f"stderr orig={e1!r} mine={e2!r}")
    if "panic:" in e1:
        # check mine also panics
        if "panic:" not in e2: ok=False; reasons.append("expected panic")
    if set(o1)!=set(o2): ok=False; reasons.append(f"files {sorted(o1)} vs {sorted(o2)}")
    else:
        for k in o1:
            if o1[k]!=o2[k]:
                ok=False; reasons.append(f"file {k} differs len {len(o1[k])} vs {len(o2[k])}")
                open("/tmp/dt_orig","wb").write(o1[k]); open("/tmp/dt_mine","wb").write(o2[k])
    print(("PASS " if ok else "FAIL ")+title)
    for r in reasons: print("  ",r[:3000])
    return ok
PY
